insert into public.names (id, arabic, transliteration, translation, explanation, source_references, content_status)
values
(1, 'الرَّحْمَٰنُ', 'Ar-Raḥmān', 'Всемилостивый', 'Обладатель всеобъемлющей милости. В Коране это имя напоминает о широте милости Аллаха ко всему творению.', '[{"reference":"1:1; 17:110"}]'::jsonb, 'published'),
(2, 'الرَّحِيمُ', 'Ar-Raḥīm', 'Милующий', 'Тот, чья милость совершенна. Верующий обращается к Аллаху с надеждой на Его милость и прощение.', '[{"reference":"1:3; 2:163"}]'::jsonb, 'published'),
(3, 'الْمَلِكُ', 'Al-Malik', 'Истинный Владыка', 'Аллаху принадлежит совершенная власть над небесами и землёй. Его власть не ограничена и не прекращается.', '[{"reference":"20:114; 59:23"}]'::jsonb, 'published'),
(4, 'الْقُدُّوسُ', 'Al-Quddūs', 'Пречистый', 'Пречистый от всякого недостатка и всего, что не подобает Его величию.', '[{"reference":"59:23; 62:1"}]'::jsonb, 'published'),
(5, 'السَّلَامُ', 'As-Salām', 'Источник мира и совершенства', 'Аллах пречист от недостатков; от Него исходят безопасность и мир для тех, кому Он дарует их.', '[{"reference":"59:23"}]'::jsonb, 'published'),
(6, 'الْمُؤْمِنُ', 'Al-Mu’min', 'Дарующий безопасность', 'Аллах подтверждает истину Своих посланников и дарует безопасность Своим рабам по Своей мудрости.', '[{"reference":"59:23"}]'::jsonb, 'published'),
(7, 'الْمُهَيْمِنُ', 'Al-Muhaymin', 'Хранитель и Свидетель', 'Аллах наблюдает за творением, хранит его и ничто не скрыто от Него.', '[{"reference":"59:23"}]'::jsonb, 'published'),
(8, 'الْعَزِيزُ', 'Al-‘Azīz', 'Могущественный', 'Обладатель непреодолимого могущества и почёта. Никто не способен одолеть Его.', '[{"reference":"3:6; 59:23"}]'::jsonb, 'published'),
(9, 'الْجَبَّارُ', 'Al-Jabbār', 'Всеподчиняющий Своей воле', 'Аллах обладает совершенной властью и силой; Его решение не может быть отменено.', '[{"reference":"59:23"}]'::jsonb, 'published'),
(10, 'الْمُتَكَبِّرُ', 'Al-Mutakabbir', 'Превознесённый', 'Только Аллах обладает истинным величием и совершенством, свободным от всякого недостатка.', '[{"reference":"59:23"}]'::jsonb, 'published'),
(11, 'الْخَالِقُ', 'Al-Khāliq', 'Творец', 'Аллах создаёт всё сущее по Своей воле и мудрости.', '[{"reference":"59:24"}]'::jsonb, 'published'),
(12, 'الْبَارِئُ', 'Al-Bāri’', 'Создатель', 'Аллах приводит творения к существованию, создавая их без предшествующего образца.', '[{"reference":"59:24"}]'::jsonb, 'published'),
(13, 'الْمُصَوِّرُ', 'Al-Muṣawwir', 'Придающий облик', 'Аллах придаёт творениям их формы и особенности так, как пожелает.', '[{"reference":"59:24"}]'::jsonb, 'published'),
(14, 'الْغَفَّارُ', 'Al-Ghaffār', 'Многократно Прощающий', 'Аллах прощает грехи тем, кто искренне кается и обращается к Нему.', '[{"reference":"20:82; 38:66"}]'::jsonb, 'published'),
(15, 'الْقَهَّارُ', 'Al-Qahhār', 'Всепобеждающий', 'Всё творение подвластно Аллаху; ничто не выходит за пределы Его власти.', '[{"reference":"13:16; 39:4"}]'::jsonb, 'published'),
(16, 'الْوَهَّابُ', 'Al-Wahhāb', 'Щедро Дарующий', 'Аллах дарует блага по Своей щедрости, без того чтобы кто-либо мог обязать Его.', '[{"reference":"3:8; 38:9"}]'::jsonb, 'published'),
(17, 'الرَّزَّاقُ', 'Ar-Razzāq', 'Наделяющий уделом', 'Аллах обеспечивает пропитанием всё творение. Рабу следует искать дозволенный удел и уповать на Него.', '[{"reference":"51:58"}]'::jsonb, 'published'),
(18, 'الْفَتَّاحُ', 'Al-Fattāḥ', 'Открывающий', 'Аллах открывает пути блага и выносит справедливое решение между творениями.', '[{"reference":"34:26"}]'::jsonb, 'published'),
(19, 'الْعَلِيمُ', 'Al-‘Alīm', 'Всезнающий', 'Знание Аллаха охватывает явное и скрытое, прошлое и будущее; от Него не утаится даже малое.', '[{"reference":"2:29; 6:101"}]'::jsonb, 'published'),
(20, 'الْقَابِضُ', 'Al-Qābiḍ', 'Удерживающий', 'Аллах удерживает и ограничивает по Своей мудрости. Это имя приводится в известных перечнях; его отдельное доказательство требует проверки.', '[{"reference":"См. хадис о расширении и удержании удела"}]'::jsonb, 'published'),
(21, 'الْبَاسِطُ', 'Al-Bāsiṭ', 'Расширяющий', 'Аллах расширяет удел и милость тому, кому пожелает, согласно Своей мудрости.', '[{"reference":"См. хадис о расширении и удержании удела"}]'::jsonb, 'published'),
(22, 'الْخَافِضُ', 'Al-Khāfiḍ', 'Понижающий', 'Встречается в распространённых списках; не следует утверждать имя без проверки конкретного доказательства.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(23, 'الرَّافِعُ', 'Ar-Rāfi‘', 'Возвышающий', 'Аллах возвышает кого пожелает истинной верой, знанием и Своей милостью.', '[{"reference":"58:11; 6:83"}]'::jsonb, 'published'),
(24, 'الْمُعِزُّ', 'Al-Mu‘izz', 'Дарующий могущество', 'Истинное достоинство и власть принадлежат Аллаху; Он дарует их кому пожелает.', '[{"reference":"3:26"}]'::jsonb, 'published'),
(25, 'الْمُذِلُّ', 'Al-Mudhِلّ', 'Лишающий почёта', 'Форма встречается в распространённых перечнях; её употребление как отдельного имени требует проверки доказательства.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(26, 'السَّمِيعُ', 'As-Samī‘', 'Всеслышащий', 'Аллах слышит каждую мольбу и каждый звук, даже если они произнесены тихо.', '[{"reference":"2:127; 42:11"}]'::jsonb, 'published'),
(27, 'الْبَصِيرُ', 'Al-Baṣīr', 'Всевидящий', 'Ничто не скрыто от зрения Аллаха. Он видит явное и то, что скрыто от людей.', '[{"reference":"42:11; 17:1"}]'::jsonb, 'published'),
(28, 'الْحَكَمُ', 'Al-Ḥakam', 'Высший Судья', 'Аллах выносит окончательное и совершенное решение; Его суд основан на знании и справедливости.', '[{"reference":"6:57"}]'::jsonb, 'published'),
(29, 'الْعَدْلُ', 'Al-‘Adl', 'Справедливый', 'Аллах не поступает несправедливо ни с кем. Это известное описание Его совершенства; статус отдельного имени в перечнях обсуждается.', '[{"reference":"4:40; 10:44"}]'::jsonb, 'published'),
(30, 'اللَّطِيفُ', 'Al-Laṭīf', 'Проявляющий тонкую доброту', 'Аллах знает самые тонкие подробности и оказывает Своим рабам добро путями, которые они могут не замечать.', '[{"reference":"6:103; 42:19"}]'::jsonb, 'published'),
(31, 'الْخَبِيرُ', 'Al-Khabīr', 'Ведающий обо всём', 'Аллах полностью осведомлён о сущности вещей, намерениях и тайных обстоятельствах.', '[{"reference":"6:18; 67:14"}]'::jsonb, 'published'),
(32, 'الْحَلِيمُ', 'Al-Ḥalīm', 'Выдержанный', 'Аллах не спешит с наказанием, несмотря на ослушание рабов, и даёт им возможность покаяться.', '[{"reference":"2:225; 17:44"}]'::jsonb, 'published'),
(33, 'الْعَظِيمُ', 'Al-‘Aẓīm', 'Величайший', 'Аллах обладает абсолютным величием, превосходящим всё, что может представить творение.', '[{"reference":"2:255; 42:4"}]'::jsonb, 'published'),
(34, 'الْغَفُورُ', 'Al-Ghafūr', 'Прощающий', 'Его прощение широко; Он прощает тому, кто обращается к Нему с покаянием.', '[{"reference":"2:173; 39:53"}]'::jsonb, 'published'),
(35, 'الشَّكُورُ', 'Ash-Shakūr', 'Воздающий за благодарность', 'Аллах принимает малые благие дела и многократно вознаграждает за них по Своей щедрости.', '[{"reference":"35:30; 64:17"}]'::jsonb, 'published'),
(36, 'الْعَلِيُّ', 'Al-‘Aliyy', 'Всевышний', 'Аллах превыше Своего творения и обладает совершенным величием.', '[{"reference":"2:255; 42:4"}]'::jsonb, 'published'),
(37, 'الْكَبِيرُ', 'Al-Kabīr', 'Величайший', 'Его величие безгранично, и всё творение мало перед Его могуществом.', '[{"reference":"13:9; 22:62"}]'::jsonb, 'published'),
(38, 'الْحَفِيظُ', 'Al-Ḥafīẓ', 'Оберегающий', 'Аллах хранит творение и сохраняет дела рабов; ничто не теряется из Его знания.', '[{"reference":"11:57; 34:21"}]'::jsonb, 'published'),
(39, 'الْمُقِيتُ', 'Al-Muqīt', 'Поддерживающий', 'Аллах обеспечивает творения необходимым и обладает властью над всем, что поддерживает жизнь.', '[{"reference":"4:85"}]'::jsonb, 'published'),
(40, 'الْحَسِيبُ', 'Al-Ḥasīb', 'Достаточный и ведущий расчёт', 'Аллах достаточен Своим рабам и ведёт точный расчёт их дел.', '[{"reference":"4:6; 33:39"}]'::jsonb, 'published'),
(41, 'الْجَلِيلُ', 'Al-Jalīl', 'Обладатель величия', 'Аллах достоин высшего почитания и возвеличивания. Отдельное включение в перечень требует сверки.', '[{"reference":"55:27 — ذو الجلال والإكرام"}]'::jsonb, 'published'),
(42, 'الْكَرِيمُ', 'Al-Karīm', 'Щедрый', 'Аллах щедр в Своих дарах и милости; Он любит щедрость и благие поступки.', '[{"reference":"27:40; 82:6"}]'::jsonb, 'published'),
(43, 'الرَّقِيبُ', 'Ar-Raqīb', 'Наблюдающий', 'Аллах наблюдает за каждым делом и знает то, что скрыто в сердцах.', '[{"reference":"4:1; 5:117"}]'::jsonb, 'published'),
(44, 'الْمُجِيبُ', 'Al-Mujīb', 'Отвечающий на мольбы', 'Аллах близок к Своим рабам и отвечает на мольбу так, как пожелает и когда пожелает.', '[{"reference":"11:61"}]'::jsonb, 'published'),
(45, 'الْوَاسِعُ', 'Al-Wāsi‘', 'Всеобъемлющий', 'Знание, милость и щедрость Аллаха безграничны.', '[{"reference":"2:115; 2:261"}]'::jsonb, 'published'),
(46, 'الْحَكِيمُ', 'Al-Ḥakīm', 'Мудрый', 'Все решения и установления Аллаха основаны на совершенной мудрости.', '[{"reference":"2:32; 4:26"}]'::jsonb, 'published'),
(47, 'الْوَدُودُ', 'Al-Wadūd', 'Любящий', 'Аллах любит Своих верующих рабов и дарует им Свою милость.', '[{"reference":"11:90; 85:14"}]'::jsonb, 'published'),
(48, 'الْمَجِيدُ', 'Al-Majīd', 'Славный', 'Аллах обладает совершенной славой, благородством и величием.', '[{"reference":"11:73; 85:15"}]'::jsonb, 'published'),
(49, 'الْبَاعِثُ', 'Al-Bā‘ith', 'Воскрешающий', 'Аллах воскресит умерших и выведет людей для расчёта в День воскресения.', '[{"reference":"22:7"}]'::jsonb, 'published'),
(50, 'الشَّهِيدُ', 'Ash-Shahīd', 'Всесвидетельствующий', 'Аллах свидетельствует обо всём; ничто не происходит вне Его знания.', '[{"reference":"4:79; 22:17"}]'::jsonb, 'published'),
(51, 'الْحَقُّ', 'Al-Ḥaqq', 'Истина', 'Аллах — Истинный, Его существование и обещание истинны, а всё помимо Него нуждается в Нём.', '[{"reference":"22:6; 31:30"}]'::jsonb, 'published'),
(52, 'الْوَكِيلُ', 'Al-Wakīl', 'Попечитель', 'Аллах — наилучший Попечитель. Верующий полагается на Него, одновременно предпринимая дозволенные причины.', '[{"reference":"3:173; 39:62"}]'::jsonb, 'published'),
(53, 'الْقَوِيُّ', 'Al-Qawiyy', 'Всесильный', 'Сила Аллаха совершенна и не ослабевает.', '[{"reference":"11:66; 22:40"}]'::jsonb, 'published'),
(54, 'الْمَتِينُ', 'Al-Matīn', 'Несокрушимый', 'Аллах обладает совершенной, неистощимой силой.', '[{"reference":"51:58"}]'::jsonb, 'published'),
(55, 'الْوَلِيُّ', 'Al-Waliyy', 'Покровитель', 'Аллах покровитель верующих: поддерживает их и ведёт к свету по Своей милости.', '[{"reference":"2:257; 42:28"}]'::jsonb, 'published'),
(56, 'الْحَمِيدُ', 'Al-Ḥamīd', 'Достохвальный', 'Аллах достоин хвалы за Свои имена, качества, решения и деяния.', '[{"reference":"14:1; 31:12"}]'::jsonb, 'published'),
(57, 'الْمُحْصِي', 'Al-Muḥṣī', 'Исчисляющий', 'Аллах охватывает знанием и точным исчислением всё сущее и каждое дело.', '[{"reference":"72:28; 78:29"}]'::jsonb, 'published'),
(58, 'الْمُبْدِئُ', 'Al-Mubdi’', 'Начинающий творение', 'Аллах начинает творение без предшествующего примера и способен повторить его.', '[{"reference":"10:4; 85:13"}]'::jsonb, 'published'),
(59, 'الْمُعِيدُ', 'Al-Mu‘īd', 'Возвращающий к жизни', 'Аллах повторно создаст творения после смерти для воскресения и расчёта.', '[{"reference":"10:4; 85:13"}]'::jsonb, 'published'),
(60, 'الْمُحْيِي', 'Al-Muḥyī', 'Дарующий жизнь', 'Аллах даёт жизнь кому пожелает; оживление творения — знак Его могущества.', '[{"reference":"30:50; 57:2"}]'::jsonb, 'published'),
(61, 'الْمُمِيتُ', 'Al-Mumīt', 'Умерщвляющий', 'Аллах предопределил смерть и знает её срок для каждого творения.', '[{"reference":"3:156; 57:2"}]'::jsonb, 'published'),
(62, 'الْحَيُّ', 'Al-Ḥayy', 'Вечно Живой', 'Жизнь Аллаха совершенна, не имеет начала и конца и не подобна жизни творений.', '[{"reference":"2:255; 25:58"}]'::jsonb, 'published'),
(63, 'الْقَيُّومُ', 'Al-Qayyūm', 'Самосущий и Поддерживающий всё', 'Аллах не нуждается ни в ком, тогда как всё существующее нуждается в Нём.', '[{"reference":"2:255; 3:2"}]'::jsonb, 'published'),
(64, 'الْوَاجِدُ', 'Al-Wājid', 'Обладающий всем', 'Входит в некоторые традиционные списки; точное доказательство как отдельного имени следует проверить.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(65, 'الْمَاجِدُ', 'Al-Mājid', 'Славный и Благородный', 'Встречается в известных перечнях имён; его отдельное доказательство нуждается в редакторской сверке.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(66, 'الْوَاحِدُ', 'Al-Wāḥid', 'Единственный', 'Аллах един в Своём господстве и праве на поклонение; у Него нет сотоварищей.', '[{"reference":"2:163; 13:16"}]'::jsonb, 'published'),
(67, 'الصَّمَدُ', 'Aṣ-Ṣamad', 'Самодостаточный', 'Все творения нуждаются в Аллахе, а Он ни в ком не нуждается. Сура «аль-Ихляс» раскрывает этот великий смысл.', '[{"reference":"112:2"}]'::jsonb, 'published'),
(68, 'الْقَادِرُ', 'Al-Qādir', 'Всемогущий', 'Аллах способен на всякую вещь; ничто не является для Него невозможным.', '[{"reference":"6:65; 17:99"}]'::jsonb, 'published'),
(69, 'الْمُقْتَدِرُ', 'Al-Muqtadir', 'Всесильный', 'Его могущество совершенно, и Он осуществляет то, что пожелает.', '[{"reference":"18:45; 54:55"}]'::jsonb, 'published'),
(70, 'الْمُقَدِّمُ', 'Al-Muqaddim', 'Выдвигающий вперёд', 'Аллах выдвигает вперёд и приближает кого пожелает согласно Своей мудрости; отдельное доказательство имени проверяется.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(71, 'الْمُؤَخِّرُ', 'Al-Mu’akhkhir', 'Отодвигающий', 'Аллах откладывает и оставляет позади то, что пожелает, согласно Своей мудрости; отдельное доказательство имени проверяется.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(72, 'الْأَوَّلُ', 'Al-Awwal', 'Первый', 'До Аллаха не было ничего; Он существовал всегда и не имеет начала.', '[{"reference":"Хадис: Сахих Муслим 2713"}]'::jsonb, 'published'),
(73, 'الْآخِرُ', 'Al-Ākhir', 'Последний', 'После исчезновения творения останется Аллах; у Него нет конца.', '[{"reference":"Хадис: Сахих Муслим 2713"}]'::jsonb, 'published'),
(74, 'الظَّاهِرُ', 'Aẓ-Ẓāhir', 'Явный', 'Над Аллахом нет ничего; Его знамения указывают на Его существование и могущество.', '[{"reference":"Хадис: Сахих Муслим 2713"}]'::jsonb, 'published'),
(75, 'الْبَاطِنُ', 'Al-Bāṭin', 'Сокровенный', 'Ничто не ближе к творению знанием, чем Аллах; Он знает всё скрытое.', '[{"reference":"Хадис: Сахих Муслим 2713"}]'::jsonb, 'published'),
(76, 'الْوَالِي', 'Al-Wālī', 'Управляющий', 'Аллах распоряжается делами творения и управляет всем сущим.', '[{"reference":"13:11 — له معقبات"}]'::jsonb, 'published'),
(77, 'الْمُتَعَالِي', 'Al-Muta‘ālī', 'Превыше всего', 'Аллах превыше творения и любых недостатков.', '[{"reference":"13:9"}]'::jsonb, 'published'),
(78, 'الْبَرُّ', 'Al-Barr', 'Благодетельный', 'Аллах проявляет великое добро к Своим рабам и исполняет обещанное.', '[{"reference":"52:28"}]'::jsonb, 'published'),
(79, 'التَّوَّابُ', 'At-Tawwāb', 'Принимающий покаяние', 'Аллах открывает дверь покаяния и принимает искреннее возвращение раба к Нему.', '[{"reference":"2:37; 9:104"}]'::jsonb, 'published'),
(80, 'الْمُنْتَقِمُ', 'Al-Muntaqim', 'Воздающий по справедливости', 'Аллах воздаёт преступившим пределы справедливо. Нельзя понимать это имя как человеческую мстительность.', '[{"reference":"32:22; 43:41"}]'::jsonb, 'published'),
(81, 'الْعَفُوُّ', 'Al-‘Afūw', 'Стирающий грехи', 'Аллах не только прощает, но и стирает грехи того, кому пожелает.', '[{"reference":"4:99; 4:149"}]'::jsonb, 'published'),
(82, 'الرَّؤُوفُ', 'Ar-Ra’ūf', 'Сострадательный', 'Аллах проявляет к Своим рабам особую мягкость и сострадание.', '[{"reference":"2:143; 9:117"}]'::jsonb, 'published'),
(83, 'مَالِكُ الْمُلْكِ', 'Mālik al-Mulk', 'Властелин царства', 'Вся власть принадлежит Аллаху; Он дарует её и лишает её по Своей воле.', '[{"reference":"3:26"}]'::jsonb, 'published'),
(84, 'ذُو الْجَلَالِ وَالْإِكْرَامِ', 'Dhū al-Jalāli wa-l-Ikrām', 'Обладатель величия и щедрости', 'Аллах достоин величайшего почитания и обладает совершенной щедростью.', '[{"reference":"55:27; 55:78"}]'::jsonb, 'published'),
(85, 'الْمُقْسِطُ', 'Al-Muqsiṭ', 'Устанавливающий справедливость', 'Аллах справедлив в Своих решениях; слово встречается в Коране как описание справедливости.', '[{"reference":"3:18"}]'::jsonb, 'published'),
(86, 'الْجَامِعُ', 'Al-Jāmi‘', 'Собирающий', 'Аллах соберёт людей в День воскресения, когда они предстанут перед Ним.', '[{"reference":"3:9"}]'::jsonb, 'published'),
(87, 'الْغَنِيُّ', 'Al-Ghaniyy', 'Ни в ком не нуждающийся', 'Аллах абсолютно самодостаточен, а все творения нуждаются в Нём.', '[{"reference":"2:263; 35:15"}]'::jsonb, 'published'),
(88, 'الْمُغْنِي', 'Al-Mughnī', 'Обогащающий', 'Аллах обогащает и обеспечивает кого пожелает; истинное богатство — по Его дару.', '[{"reference":"53:48"}]'::jsonb, 'published'),
(89, 'الْمَانِعُ', 'Al-Māni‘', 'Удерживающий и защищающий', 'Аллах удерживает то, что пожелает, и никто не может воспрепятствовать Его решению. Отдельное имя проверяется.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(90, 'الضَّارُّ', 'Aḍ-Ḍārr', 'Определяющий испытания', 'Ничто не происходит вне предопределения Аллаха. Имя нельзя употреблять отдельно от контекста и без проверки.', '[{"reference":"6:17 — смысл предопределения"}]'::jsonb, 'published'),
(91, 'النَّافِعُ', 'An-Nāfi‘', 'Дарующий пользу', 'Всякая польза приходит только с дозволения Аллаха; отдельное включение в список проверяется.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(92, 'النُّورُ', 'An-Nūr', 'Свет', 'Аллах — Свет небес и земли; Он ведёт к свету веры и истины.', '[{"reference":"24:35"}]'::jsonb, 'published'),
(93, 'الْهَادِي', 'Al-Hādī', 'Ведущий прямым путём', 'Аллах ведёт к истине кого пожелает; раб просит Его о прямом пути.', '[{"reference":"22:54; 25:31"}]'::jsonb, 'published'),
(94, 'الْبَدِيعُ', 'Al-Badī‘', 'Первосоздатель', 'Аллах создал небеса и землю без предшествующего образца.', '[{"reference":"2:117; 6:101"}]'::jsonb, 'published'),
(95, 'الْبَاقِي', 'Al-Bāqī', 'Вечный', 'Всё творение исчезнет, а Аллах останется. Это верный смысл, но отдельное имя требует сверки.', '[{"reference":"55:26–27"}]'::jsonb, 'published'),
(96, 'الْوَارِثُ', 'Al-Wārith', 'Наследующий всё', 'После исчезновения творений Аллах останется; Ему принадлежит всё, что было у них.', '[{"reference":"15:23; 21:89"}]'::jsonb, 'published'),
(97, 'الرَّشِيدُ', 'Ar-Rashīd', 'Направляющий к верному', 'Входит в часть традиционных перечней; доказательство как отдельного имени требует проверки.', '[{"reference":"Требует отдельной проверки"}]'::jsonb, 'published'),
(98, 'الصَّبُورُ', 'Aṣ-Ṣabūr', 'Терпеливый', 'Аллах не спешит с наказанием, хотя способен на него. Имя приводится в известных списках; статус нуждается в сверке.', '[{"reference":"Смысл подтверждается хадисами о терпении Аллаха"}]'::jsonb, 'published'),
(99, 'اللّٰهُ', 'Allāh', 'Аллах', 'Величайшее собственное имя Господа миров, Единственного, Кто достоин поклонения. Все прекрасные имена принадлежат Ему.', '[{"reference":"1:1; 2:255; 59:22–24"}]'::jsonb, 'published')
