-- Populate the 99-name learning catalogue used by the Asma Ul Husna app.
-- Run once in Supabase SQL Editor after the base schema exists.
-- The course page explicitly explains that popular numbered lists differ;
-- this seed is a teaching list, not a claim of one universally agreed enumeration.

on conflict (id) do update set
  arabic = excluded.arabic,
  transliteration = excluded.transliteration,
  translation = excluded.translation,
  explanation = excluded.explanation,
  source_references = excluded.source_references,
  content_status = excluded.content_status,
  updated_at = now();
